/*
 * Binary models generated by the Nexus French-model pipeline (stage 3).
 * The ESP32-S3 MMU reads these read-only sections directly from mapped flash.
 * Keep these paths in sync with the stage-3 artifact publishing workflow.
 */
.section .rodata.nexus_llm_model,"a",@progbits
.balign 16
.global nexus_model_start
.type nexus_model_start, @object
nexus_model_start:
.incbin "src/narrator/local_llm/assets/model_lecarnet_q4.bin"
.global nexus_model_end
nexus_model_end:

.section .rodata.nexus_llm_tokenizer,"a",@progbits
.balign 16
.global nexus_tokenizer_start
.type nexus_tokenizer_start, @object
nexus_tokenizer_start:
.incbin "src/narrator/local_llm/assets/tokenizer_lecarnet_ctk2.bin"
.global nexus_tokenizer_end
nexus_tokenizer_end:
